-- Synthetic 3-Year Co-Living Dataset with KYC, Payment Systems, App Integrations & Indian Legislature
-- Disclaimer: All personal IDs (Aadhaar, PAN, DL, FRRO) are fictional synthetic placeholders.

CREATE TABLE residents_master (
    resident_id VARCHAR(10) PRIMARY KEY,
    full_name VARCHAR(100) NOT NULL,
    nationality VARCHAR(30) NOT NULL,
    room_type VARCHAR(40) NOT NULL,
    room_no VARCHAR(20) NOT NULL,
    primary_auth_doc_type VARCHAR(80),
    simulated_doc_numbers VARCHAR(150),
    aadhaar_masked_simulated VARCHAR(40),
    pan_simulated VARCHAR(20),
    driving_license_simulated VARCHAR(30),
    employer_organization VARCHAR(100),
    work_permit_or_company_id VARCHAR(50),
    payment_system VARCHAR(80),
    payment_gateway_integration_id VARCHAR(50),
    application_id VARCHAR(40),
    tenant_app_user_uuid VARCHAR(40),
    app_integration_stack VARCHAR(120),
    payment_regulation VARCHAR(150),
    applicable_legislature TEXT
);


CREATE TABLE monthly_billing_ledger (
    billing_id INT AUTO_INCREMENT PRIMARY KEY,
    billing_month VARCHAR(7) NOT NULL,
    resident_id VARCHAR(10) NOT NULL,
    base_rent_inr INT NOT NULL,
    food_plan_inr INT NOT NULL,
    late_night_orders INT NOT NULL,
    avg_delivery_dist_km DECIMAL(4,1) NOT NULL,
    late_night_spend_inr INT NOT NULL,
    total_monthly_bill_inr INT NOT NULL,
    FOREIGN KEY (resident_id) REFERENCES residents_master(resident_id)
);

